CREATE COLUMN TABLE "TEST_AP"."DAR1" ("ArcEntry" INTEGER CS_INT NOT NULL , "Line_ID" INTEGER CS_INT NOT NULL , "DocType" NVARCHAR(20), "DocNum" INTEGER CS_INT, "DocAbs" INTEGER CS_INT, "Total" DECIMAL(21,6) CS_FIXED, "RefDate" LONGDATE CS_LONGDATE, "ClusterId" INTEGER CS_INT, "Remarks" NVARCHAR(100), "KeySeg1" NVARCHAR(15), "KeySeg2" NVARCHAR(15), "KeySeg3" NVARCHAR(15), "KeySeg4" NVARCHAR(15), "KeySeg5" NVARCHAR(15), "KeySeg6" NVARCHAR(15), "KeySeg7" NVARCHAR(20), "KeySeg8" NVARCHAR(15), "KeySeg9" NVARCHAR(15), "KeySeg10" NVARCHAR(15), "Series" INTEGER CS_INT, "DocSubType" NVARCHAR(2) DEFAULT '--', "PIndicator" NVARCHAR(10) DEFAULT ' ', "Instance" SMALLINT CS_INT DEFAULT 0, "Segment" SMALLINT CS_INT DEFAULT 0, "CardCode" NVARCHAR(15), PRIMARY KEY ("ArcEntry", "Line_ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."DAR1" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$DocAbs$DocType$','DocAbs','DocType'));
